import { expect, it, vi } from "vitest";
import { render, screen } from "@testing-library/react";

type Post = { id: string; title: string };
type LoadPosts = () => Promise<Post[]>;

it("renders posts from a controlled service", async () => {
  const loadPosts = vi.fn<LoadPosts>().mockResolvedValue([
    { id: "1", title: "A sample post" },
  ]);

  render(<PostsPage loadPosts={loadPosts} />);

  expect(await screen.findByRole("heading", { name: "A sample post" }))
    .toBeInTheDocument();
  expect(loadPosts).toHaveBeenCalledTimes(1);
});

